     "method": {"type": "string", "default": "POST"},
     "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
     "body": {"type": "object", "required": ["customer_id", "outcome"], "properties": {
       "customer_id": {"type": "string", "default": "{{customer_id}}"},
       "outcome": {"type": "string", "enum": ["promise", "paid", "transferred", "no_promise", "not_verified", "not_reached"], "default": "{{close_outcome}}"},
       "reason": {"type": "string", "description": "Left out for promise and paid.", "default": "{{close_reason}}"}}}}}},
   "pre_process_code": "import json
try:
    b = config.get('body')
    if isinstance(b, dict):
        out = vars.get('close_outcome') or 'not_reached'
        rs = vars.get('close_reason') or 'unclear'
        tr = vars.get('transfer_reason') or 'none'
        pc = int(vars.get('promise_count') or 0)
        if tr != 'none':
            out, rs = 'transferred', tr
        elif pc > 0:
            out, rs = 'promise', ''
        elif vars.get('id_state') == 'passed':
            notes = dict()
            for item in json.loads(vars.get('notes_json') or '[]'):
                notes.setdefault(str(item[0]), str(item[1]))
            order = json.loads(vars.get('product_order') or '[]')
            if order and all(notes.get(p) == 'paid' for p in order):
                out, rs = 'paid', ''
            else:
                for p in order:
                    r = notes.get(p)
                    if r and r != 'paid':
                        out, rs = 'no_promise', r
                        break
        b['outcome'] = out
        if out in ('promise', 'paid') or not rs:
            b.pop('reason', None)
        else:
            b['reason'] = rs
except Exception:
    pass
",
   "post_process_code": "try:
    result.pop('header', None)
    d = result.get('data')
    if isinstance(d, dict):
        d['what_to_do_next'] = 'The call is closed. Say nothing more.'
except Exception:
    pass
"}
 ]
}

