    "code": {"type": "string", "default": "import datetime
import json
WEEKDAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']
MONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']

def parse_now(value):
    s = str(value or '').strip().replace(' ', 'T').rstrip('Z')
    for fmt, size in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):
        try:
            return datetime.datetime.strptime(s[:size], fmt)
        except ValueError:
            pass
    raise ValueError('cannot read now')

def is_bd(d, hol):
    return d.weekday() < 5 and d not in hol

def next_bd(d, hol):
    d = d + datetime.timedelta(days=1)
    while not is_bd(d, hol):
        d = d + datetime.timedelta(days=1)
    return d

def add_bd(d, n, hol):
    for _ in range(int(n)):
        d = next_bd(d, hol)
    return d

def last_bd_week(d, hol):
    mon = d - datetime.timedelta(days=d.weekday())
    day = mon + datetime.timedelta(days=4)
    while day >= mon:
        if is_bd(day, hol):
            return day
        day = day - datetime.timedelta(days=1)
    return None

def spoken(d):
    return WEEKDAYS[d.weekday()].title() + ' ' + str(d.day) + ' ' + MONTHS[d.month - 1].title()

def money(v):
    v = round(float(v or 0), 2)
    return '{:,.0f}'.format(v) if v == int(v) else '{:,.2f}'.format(v)

def as_list(value):
    if isinstance(value, list):
        return value
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except ValueError:
            return []
    if isinstance(value, dict):
        return [value]
    return value if isinstance(value, list) else []

def list_from_vars(vars, name, prefixes):
    found = as_list(vars.get(name)) if vars.get(name) not in (None, '') else []
    if found:
        return found
    for prefix in prefixes:
        rows = dict()
        start = prefix + '.'
        for key, value in vars.items():
            if not str(key).startswith(start):
                continue
            rest = str(key)[len(start):]
            idx, _, field = rest.partition('.')
            if idx.isdigit():
                if field:
                    rows.setdefault(int(idx), dict())[field] = value
                else:
                    rows[int(idx)] = value
        if rows:
            return [rows[i] for i in sorted(rows)]
        whole = vars.get(prefix)
        if whole not in (None, ''):
            got = as_list(whole)
            if got:
                return got
    return []

HOL = set(datetime.date.fromisoformat(x) for x in ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01'])
BANDS = [(1, 7, 12, 1, 'early'), (8, 45, 7, 2, 'late')]
LABEL = dict(personal_loan='personal loan', car_loan='car loan', credit_card='credit card')
try:
    now = parse_now(vars.get('now'))
    today = now.date()
    items = list_from_vars(vars, 'products', ['load_account_response.data.products', 'get_account_response.data.products'])
    wk_end = last_bd_week(today, HOL)
    if wk_end is None or wk_end <= today:
        wk_end = last_bd_week(today + datetime.timedelta(days=7), HOL)
    lines, says, order, states = [], [], [], []
    for n, it in enumerate(items, 1):
        pid = str(it.get('product_id'))
        typ = str(it.get('type'))
        days = int(float(it.get('days_late') or 0))
        band = next((b for b in BANDS if b[0] <= days <= b[1]), BANDS[-1])
        deadline = add_bd(today, band[2], HOL)
        a1 = min(wk_end, deadline) if wk_end else deadline
        if typ == 'credit_card':
            name = 'credit card ending ' + str(it.get('card_last4') or '')
            floor = it.get('minimum_payment')
        else:
            name = LABEL.get(typ, typ.replace('_', ' '))
            floor = it.get('instalment_amount')
        due, fl = money(it.get('past_due')), money(floor)
        order.append(pid)
        states.append('Your ' + name + ' is ' + due + ' past due and ' + str(days) + ' days late.')
        lines.append('Product ' + str(n) + ': ' + name + ', product_id ' + pid + '. Past due (full amount): ' + due + '. Days late: ' + str(days) + ' (' + band[4] + ' band). Floor (lowest amount): ' + fl + '. Deadline (latest promise date): ' + spoken(deadline) + ' (' + deadline.isoformat() + '). Persuasion attempts allowed: ' + str(band[3]) + '.')
        says.append('For product ' + str(n) + ' (' + name + '):')
        says.append('  - Full amount too much, offer the floor once: "Could you pay ' + fl + ' instead? The rest stays overdue."')
        says.append('  - Attempt 1 after a flat refusal (full amount): "Could you pay the full ' + due + ' by ' + spoken(a1) + '?"')
        says.append('  - Attempt 1 instead, if the customer already said the full amount is too much: "Could you pay ' + fl + ' by ' + spoken(a1) + '? The rest stays overdue."')
        if band[3] >= 2:
            says.append('  - Attempt 2, after a refusal of attempt 1: "Could you pay ' + fl + ' by ' + spoken(deadline) + '? The rest stays overdue."')
        else:
            says.append('  - No attempt 2 for this product: after attempt 1 is refused, stop.')
        says.append('  - Date after the deadline: "The latest date I can record is ' + spoken(deadline) + '. Can you pay by then?"')
    cal = []
    for i in range(0, 22):
        d = today + datetime.timedelta(days=i)
        tag = 'business day' if is_bd(d, HOL) else ('NOT a business day, offer ' + spoken(next_bd(d, HOL)) + ' instead')
        cal.append(d.isoformat() + ' ' + spoken(d) + ': ' + tag + ('  (today)' if i == 0 else ''))
    mon = today - datetime.timedelta(days=today.weekday())
    wd = []
    for k in range(7):
        wd.append('this ' + WEEKDAYS[k].title() + ' = ' + spoken(mon + datetime.timedelta(days=k)) + '; next ' + WEEKDAYS[k].title() + ' = ' + spoken(mon + datetime.timedelta(days=7 + k)))
    first_ask = 'Can you make this payment today?' if len(items) <= 1 else 'Can you pay all of them today?'
    vars['statement_text'] = 'I am calling from the collections team about a late payment. ' + ' '.join(states) + ' ' + first_ask
    vars['facts_text'] = ('Today is ' + spoken(today) + ' (' + today.isoformat() + ').\n' + '\n'.join(lines) +
        '\n\nSay these sentences exactly when they apply:\n' + '\n'.join(says) +
        '\n  - Read-back: name each product, its amount and its date, then ask: "Do you confirm?"' +
        '\n  - After the promises are recorded: "You will receive a text message confirming this promise."' +
        '\n\nCalendar (a promise date must be a business day from today up to the product deadline):\n' + '\n'.join(cal) +
        '\n\nWeekday words (next means the following calendar week):\n' + '\n'.join(wd))
    vars['product_order'] = json.dumps(order)
    vars['product_count'] = str(len(order))
    vars['facts_state'] = 'ok' if order else 'empty'
except Exception:
    vars['statement_text'] = 'I am calling from the collections team about a late payment.'
    vars['facts_text'] = 'The account details could not be read. Say you do not have that information.'
    vars['product_count'] = '0'
    vars['facts_state'] = 'error'
vars['close_outcome'] = 'no_promise'
vars['close_reason'] = 'refused'
