            floor = it.get('instalment_amount')
        due, fl = money(it.get('past_due')), money(floor)
        order.append(pid)
        dl = [today + datetime.timedelta(days=k) for k in range((deadline - today).days + 1)]
        checks[pid] = dict(floor=float(floor or 0), due=float(it.get('past_due') or 0), dates=[x.isoformat() for x in dl if is_bd(x, HOL)], deadline=spoken(deadline), floor_s=fl)
        states.append('Your ' + name + ' is ' + due + ' past due and ' + str(days) + ' days late.')
        lines.append('Product ' + str(n) + ': ' + name + ', product_id ' + pid + '. Past due (full amount): ' + due + '. Days late: ' + str(days) + ' (' + band[4] + ' band). Floor (lowest amount): ' + fl + '. Deadline (latest promise date): ' + spoken(deadline) + ' (' + deadline.isoformat() + '). Persuasion attempts allowed: ' + str(band[3]) + '.')
        says.append('For product ' + str(n) + ' (' + name + '):')
