    "code": {"type": "string", "default": "import datetime
WEEKDAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']
MONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']

def parse_now(value):
    s = str(value or '').strip().replace(' ', 'T').rstrip('Z')
    for fmt, size in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):
        try:
            return datetime.datetime.strptime(s[:size], fmt)
        except ValueError:
            pass
    raise ValueError('cannot read now')

def is_bd(d, hol):
    return d.weekday() < 5 and d not in hol

def next_bd(d, hol):
    d = d + datetime.timedelta(days=1)
    while not is_bd(d, hol):
        d = d + datetime.timedelta(days=1)
    return d

def spoken(d):
    return WEEKDAYS[d.weekday()].title() + ' ' + str(d.day) + ' ' + MONTHS[d.month - 1].title()

HOL = set(datetime.date.fromisoformat(x) for x in ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01'])
try:
    now = parse_now(vars.get('now'))
    today = now.date()
    hm = now.strftime('%H:%M')
    nxt = next_bd(today, HOL)
    parts = []
    if is_bd(today, HOL) and hm < '19:00':
        start = ('later than ' + hm) if hm >= '10:00' else 'from 10:00'
        parts.append('today, ' + spoken(today) + ' (' + today.isoformat() + '), ' + start + ' up to 19:00')
    parts.append(spoken(nxt) + ' (' + nxt.isoformat() + '), from 10:00 to 19:00')
    vars['cb_dates'] = ','.join(([today.isoformat()] if len(parts) > 1 else []) + [nxt.isoformat()])
    vars['callback_window_text'] = 'It is now ' + spoken(today) + ', ' + hm + '. A callback can only be booked ' + ' or '.join(parts) + ', both ends included. Any other day or time is outside the window.'
except Exception:
    vars['callback_window_text'] = 'A callback can only be booked today or the next business day, from 10:00 to 19:00, and later than now.'
vars['close_outcome'] = 'not_reached'
vars['close_reason'] = 'unclear'
vars['promise_count'] = '0'
vars['call_state'] = 'open'
